import numpy as np
import os

try:
    from scipy.optimize import linprog
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

# ---------------- Utilities ----------------

def _boundary_margins(C: np.ndarray) -> np.ndarray:
    x = C[:, 0]; y = C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _solve_lp_for_radii(C: np.ndarray):
    """
    Maximize sum r_i s.t.
      0 <= r_i <= b_i, and r_i + r_j <= ||c_i - c_j|| for all i<j.
    Returns (r, obj, ok)
    """
    n = C.shape[0]
    if n != 32 or C.shape != (32, 2):
        return None, 0.0, False
    b = _boundary_margins(C)

    if not SCIPY_AVAILABLE:
        # Conservative fallback (kept tight by margins)
        r = np.minimum(b, 1.0 / 12.0) * 0.999
        return r, float(np.sum(r)), True

    # Build pairwise constraints
    I = []
    J = []
    for i in range(n):
        for j in range(i + 1, n):
            I.append(i); J.append(j)
    I = np.array(I, dtype=int)
    J = np.array(J, dtype=int)
    D = np.linalg.norm(C[I] - C[J], axis=1)

    m = len(I)
    A_ub = np.zeros((m, n), dtype=float)
    A_ub[np.arange(m), I] = 1.0
    A_ub[np.arange(m), J] = 1.0
    b_ub = D

    c = -np.ones(n, dtype=float)
    bounds = [(0.0, float(max(0.0, bi))) for bi in b]

    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not hasattr(res, "success") or not res.success:
        return None, 0.0, False

    r = res.x.astype(float)
    return r, float(-res.fun), True

def _safety_nextafter(C: np.ndarray, r: np.ndarray) -> np.ndarray:
    """
    Replace multiplicative shrink with nextafter-based epsilon decrease:
    strictly reduces radii by the smallest representable amount toward 0,
    preserving feasibility with negligible loss in objective.
    """
    r2 = np.minimum(r, _boundary_margins(C))
    r2 = np.nextafter(r2, 0.0)
    r2 = np.maximum(r2, 1e-12)
    return r2

def _clip_box(C: np.ndarray, margin: float = 1e-9) -> np.ndarray:
    return np.clip(C, margin, 1.0 - margin)

def _validate(C: np.ndarray, r: np.ndarray) -> bool:
    if C.shape != (32, 2) or r.shape != (32,):
        return False
    if np.any(~np.isfinite(C)) or np.any(~np.isfinite(r)) or np.any(r <= 0):
        return False
    x = C[:, 0]; y = C[:, 1]
    if np.any(x - r < 0) or np.any(x + r > 1) or np.any(y - r < 0) or np.any(y + r > 1):
        return False
    diff = C[:, None, :] - C[None, :, :]
    D = np.sqrt(np.sum(diff * diff, axis=-1))
    R = r[:, None] + r[None, :]
    iu = np.triu_indices(32, 1)
    if np.any(D[iu] < R[iu] - 1e-12):
        return False
    return True

# ---------------- Baseline and persistence ----------------

def _baseline_grid_6x6_minus_corners():
    s = 1.0 / 6.0
    r0 = 0.5 * s
    xs = r0 + s * np.arange(6, dtype=float)
    ys = r0 + s * np.arange(6, dtype=float)
    centers = []
    for i in range(6):
        for j in range(6):
            if (i == 0 and j == 0) or (i == 0 and j == 5) or (i == 5 and j == 0) or (i == 5 and j == 5):
                continue
            centers.append([xs[j], ys[i]])
    C = np.array(centers, dtype=float)
    # exact r = 1/12 with an epsilon nextafter shrink
    r = np.full(32, np.nextafter(r0, 0.0), dtype=float)
    return C, r, float(np.sum(r))

SAVE_PATH = 'storage/verity/sumr32_best.npz'

def _load_persisted():
    if os.path.exists(SAVE_PATH):
        try:
            data = np.load(SAVE_PATH)
            C = data['centers'].astype(float)
            r = data['radii'].astype(float)
            if C.shape == (32, 2) and r.shape == (32,):
                return C, r, float(np.sum(r))
        except Exception:
            pass
    return None

def _save_best(C, r):
    try:
        os.makedirs(os.path.dirname(SAVE_PATH), exist_ok=True)
        np.savez(SAVE_PATH, centers=C, radii=r, obj=float(np.sum(r)))
    except Exception:
        pass

# ---------------- Alternating 5/4 row constructors ----------------

def _rows_y_positions(rows: int, margin: float):
    if rows == 1:
        return np.array([0.5], dtype=float)
    return np.linspace(margin, 1.0 - margin, rows)

def _row_x_positions_5(kind: str):
    if kind == "tight":
        return np.array([0.12, 0.32, 0.52, 0.72, 0.92])
    # "wide"
    return np.array([0.10, 0.30, 0.50, 0.70, 0.90])

def _row_x_positions_4(kind: str):
    if kind == "phase0":
        return np.array([0.125, 0.375, 0.625, 0.875])
    if kind == "phase1":
        return np.array([0.175, 0.425, 0.675, 0.925])
    # "aligned"
    return np.array([0.20, 0.40, 0.60, 0.80])

def _make_alt_rows(counts, y_margin, five_kind, four_kind):
    ys = _rows_y_positions(len(counts), y_margin)
    C = []
    for idx, k in enumerate(counts):
        if k == 5:
            xs = _row_x_positions_5(five_kind)
        else:
            xs = _row_x_positions_4(four_kind)
        for x in xs:
            C.append([x, ys[idx]])
    return _clip_box(np.array(C, dtype=float))

# ---------------- Local search (extended micro-jitter + directed push) ----------------

def _directed_push_step(C: np.ndarray, step: float, rng) -> np.ndarray:
    # Pick a circle and push it away from its nearest neighbor
    n = C.shape[0]
    i = int(rng.integers(0, n))
    diff = C - C[i]
    d2 = np.sum(diff * diff, axis=1)
    d2[i] = np.inf
    j = int(np.argmin(d2))
    v = C[i] - C[j]
    norm = np.linalg.norm(v)
    if norm == 0.0:
        v = rng.normal(0.0, 1.0, size=2)
        norm = np.linalg.norm(v)
    v = v / norm
    C_try = C.copy()
    C_try[i] = C[i] + step * v
    return _clip_box(C_try)

def _micro_jitter_optimize(C0: np.ndarray, steps: int = 320, sigma: float = 0.008, seed: int = 2025):
    rng = np.random.default_rng(seed)
    C_best = C0.copy()
    r_best, obj_best, ok = _solve_lp_for_radii(C_best)
    if not ok:
        return C0, r_best, obj_best
    accept = 0
    for t in range(steps):
        if rng.random() < 0.25:
            C_try = _directed_push_step(C_best, step=0.01, rng=rng)
        else:
            C_try = C_best.copy()
            i = int(rng.integers(0, C_try.shape[0]))
            delta = rng.normal(0.0, sigma, size=2)
            C_try[i] = _clip_box(C_try[i] + delta)
        r_try, obj_try, ok = _solve_lp_for_radii(C_try)
        if ok and obj_try > obj_best + 1e-12:
            C_best, r_best, obj_best = C_try, r_try, obj_try
            accept += 1
        # adapt sigma modestly based on recent accept rate
        if (t + 1) % 60 == 0:
            rate = accept / 60.0
            if rate < 0.2:
                sigma *= 0.9
            elif rate > 0.5:
                sigma *= 1.05
            sigma = float(np.clip(sigma, 0.004, 0.02))
            accept = 0
    return C_best, r_best, obj_best

# ---------------- Main entry ----------------

def construct_packing() -> tuple:
    n = 32

    # Strong guaranteed baseline
    C_base, r_base, obj_base = _baseline_grid_6x6_minus_corners()
    best_C, best_r, best_obj = C_base, r_base, obj_base

    # Include persisted best if any (re-solve LP and epsilon-shrink)
    persisted = None
    try:
        persisted = _load_persisted()
    except Exception:
        persisted = None
    if persisted is not None:
        Cp, rp, _ = persisted
        rp2, objp2, ok = _solve_lp_for_radii(Cp)
        if ok:
            rp2 = _safety_nextafter(Cp, rp2)
            objp2 = float(np.sum(rp2))
            if objp2 > best_obj + 1e-12:
                best_C, best_r, best_obj = Cp, rp2, objp2

    # Generate several strong 7-row alternating patterns and refine
    patterns = [
        ([5,4,5,4,5,4,5], 0.10, "wide",  "phase0"),
        ([5,4,5,4,5,4,5], 0.10, "wide",  "aligned"),
        ([5,4,5,4,5,4,5], 0.12, "tight", "phase0"),
        ([5,4,5,4,5,4,5], 0.12, "tight", "aligned"),
        ([5,4,5,4,5,4,5], 0.11, "wide",  "phase1"),
        ([5,4,5,4,5,4,5], 0.09, "tight", "phase1"),
    ]

    # Quick LP evaluation, then extended micro-jitter optimization
    for counts, y_margin, five_kind, four_kind in patterns:
        C = _make_alt_rows(counts, y_margin, five_kind, four_kind)
        r, obj, ok = _solve_lp_for_radii(C)
        if ok and obj > best_obj + 1e-12:
            best_C, best_r, best_obj = C, r, obj
        C2, r2, obj2 = _micro_jitter_optimize(C, steps=360, sigma=0.0075, seed=2026)
        if obj2 > best_obj + 1e-12:
            best_C, best_r, best_obj = C2, r2, obj2

    # Final epsilon-shrink using nextafter and validation; fallback if needed
    best_r = _safety_nextafter(best_C, best_r)
    if not _validate(best_C, best_r) or best_obj < obj_base - 1e-9:
        return C_base, r_base

    _save_best(best_C, best_r)
    return best_C, best_r
